    static String declaring(Member member,Function<String,ClassNode> classes,Set<String>seen){if(!seen.add(member.owner))return null;ClassNode type=classes.apply(member.owner);if(type==null)return null;if(find(type,member.name,member.descriptor)!=null)return type.name;if(type.superName!=null){String inherited=declaring(new Member(type.superName,member.name,member.descriptor),classes,seen);if(inherited!=null)return inherited;}for(String face:type.interfaces){String inherited=declaring(new Member(face,member.name,member.descriptor),classes,seen);if(inherited!=null)return inherited;}return null;}
