    private static boolean result(Tree tree,int value){return tree.equals(new Result(value));}
    static MethodNode find(ClassNode owner,String name,String desc){return owner.methods.stream().filter(m->m.name.equals(name)&&m.desc.equals(desc)).findFirst().orElse(null);}
    private static List<AbstractInsnNode>code(MethodNode method){List<AbstractInsnNode>out=new ArrayList<>();for(AbstractInsnNode i:method.instructions)if(i.getOpcode()>=0)out.add(i);return out;}
    private static boolean aload(AbstractInsnNode i,int slot){return i instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==slot;}
    private static AbstractInsnNode next(AbstractInsnNode i){while(i!=null&&i.getOpcode()<0)i=i.getNext();return i;}
